// Package ps2hdl embeds the license texts and the icon shown by the application
// (About → License / Third-party licenses).
package ps2hdl

import _ "embed"

// License is the GNU General Public License of the program.
//
//go:embed LICENSE
var License string

// ThirdPartyNotices lists every bundled component with its full license text
// (generated by scripts/gen_notices.py).
//
//go:embed licenses/THIRD_PARTY_NOTICES.txt
var ThirdPartyNotices string

// AppIcon is the application icon (assets/icon, rendered by make icons), used
// for the windows and the header of the main window.
//
//go:embed assets/icon/icon-256.png
var AppIcon []byte
